import { test, expect } from '@playwright/test';

test('User can search flights from Delhi to Mumbai for a selected departure date', async ({ page }) => {
  await page.goto('https://www.ixigo.com/');
  await page.fill('#source', 'Delhi');
  await page.fill('#destination', 'Mumbai');
  await page.selectOption('#dep', 'Today');
  await page.click('#search');
  await page.waitForSelector('#flight-search-results');
  const resultText = await page.textContent('#flight-search-results > div > h2');
  expect(resultText).toContain('Search results are displayed with flight details');
}

test('No flights available for a selected departure date', async ({ page }) => {
  await page.goto('https://www.ixigo.com/');
  await page.fill('#source', 'Invalid Source');
  await page.fill('#destination', 'Invalid Destination');
  await page.selectOption('#dep', 'Past Date');
  await page.click('#search');
  await page.waitForSelector('.no-results');
  const resultText = await page.textContent('.no-results > span');
  expect(resultText).toContain('No flights available');
}

