test('User can search flights from Delhi to Mumbai for a selected departure date with a specific filter applied', async ({ page }) => {
  await page.goto('https://www.ixigo.com/');
  await page.fill('#source', 'Delhi');
  await page.fill('#destination', 'Mumbai');
