test('Validation error for invalid input', async ({ page }) => {
  await page.goto('https://www.ixigo.com/');
  await page.fill('#source', 'Invalid Source');
  await page.fill('#destination', 'Invalid Destination');
  await page.selectOption('#dep', 'Invalid Date');
  await page.click('#search');
  const errorText = await page.textContent('.error-message');
  expect(errorText).toContain('Validation error');
}

test('Error handling for network issue', async ({ page }) => {
  await page.goto('https://www.ixigo.com/');
  await page.click('#search');
  await page.locator('body').click();
  await page.waitForSelector('.error-message');
  const errorText = await page.textContent('.error-message');
  expect(errorText).toContain('Error message');
})
